const onResearchedNews = [{"id":"suseong-nutrition-sharing","type":"news","verified":true,"category":"나눔 활동","date":"2026.11.12","publishedDate":"2026-11-16","title":"대구도우누리 등 3개 기관·단체, 통합돌봄 대상자에 영양식 기탁","org":"사회적협동조합 대구도우누리","memberId":"daegu-dounuri","photoKey":"news-suseong-nutrition","url":"https://www.suseong.kr/news/index.do?menu_id=00031461&menu_link=%2Ffront%2Fnews%2FselectIcmsArticle.do%3Farticle_id%3DARTICLE_00019243","source":"대구 수성구청 행복수성뉴스 · 2026.11.16","body":"사회적협동조합 대구도우누리와 대구재가요양기관연합회 수성지회, 다정실버주간보호센터가 2026년 11월 12일 수성구청에 영양식과 영양음료를 전달했습니다. 세 기관·단체가 함께 마련한 물품은 총 300만 원 상당입니다.\n\n수성구는 기탁 물품을 취약계층 통합돌봄 대상자에게 전달할 예정이라고 밝혔습니다. 지역의 돌봄 제공기관이 이웃의 건강한 생활을 위해 함께한 나눔 활동입니다.\n\n사진은 이 행사에 참여한 대구재가요양기관연합회 수성지회의 기념촬영이며, 대구도우누리의 개별 기탁 사진은 기관 소개에서 볼 수 있습니다."},{"id":"sdl-geochang-workshop","type":"news","verified":true,"category":"조합원 활동","date":"2025.08.30 게시","publishedDate":"2025-08-30","title":"사회복지디자인연구소, 거창 워크숍에서 일상과 통합돌봄을 돌아보다","org":"사회복지디자인연구소사회적협동조합","memberId":"welfare-design","photoKey":"news-sdl-workshop","url":"https://www.dgpublic.org/web/jhboard/view.php?desc=desc&id=active1&no=4054&page=29&page_num=12&select_arrange=reg_date","source":"대구시민공익활동지원센터 참여후기 · 2025.08.30","body":"사회복지디자인연구소사회적협동조합은 거창에서 진행한 조합원 워크숍 후기를 대구시민공익활동지원센터에 공개했습니다. 조합원들은 함께 쉬고 대화하는 시간을 갖고 월평빌라를 방문하며 일상과 돌봄에 관해 생각을 나눴습니다.\n\n사진은 워크숍 중 거창 창포원에서 족욕을 체험하는 조합원들의 모습입니다.\n\n이 글의 날짜는 참여후기 게시일입니다. 자세한 활동 내용은 원문에서 확인할 수 있습니다."},{"id":"with-activity-27","type":"news","verified":true,"memberId":"with-medical","org":"위드의료복지사회적협동조합","category":"기관 활동","title":"합천 수해지역 의료 봉사활동","date":"2025.07.23","publishedDate":"2025-07-25","url":"https://www.withmedcoop.com/bbs/board.php?bo_table=sub0204&wr_id=27&theme_type=main1","source":"위드의료복지사회적협동조합","photoKey":"with-27-3","body":"위드는 2025년 7월 23일 합천 수해지역을 찾아 의료봉사와 복구 지원에 참여했습니다. 무봉관 실내체육관에 마련된 현장에서 주민들을 만나 필요한 의료 지원과 도움을 나눴습니다.\n\n사진은 기관이 공개한 해당 의료봉사 현장입니다."},{"id":"with-activity-28","type":"news","verified":true,"memberId":"with-medical","org":"위드의료복지사회적협동조합","category":"기관 활동","title":"위드 신규 조합원 환영회, 즐거운 시간을 가졌습니다.","date":"2025.07.24","publishedDate":"2025-07-25","url":"https://www.withmedcoop.com/bbs/board.php?bo_table=sub0204&wr_id=28&theme_type=main1","source":"위드의료복지사회적협동조합","photoKey":"with-28-3","body":"위드는 2025년 7월 24일 위드의원에서 제1회 신규 조합원 환영회를 진행했습니다. 새로 참여한 조합원들이 한자리에 모여 인사를 나누고 함께하는 시간을 가졌습니다.\n\n기관의 공식 갤러리에 환영회와 기념촬영 모습이 공개되어 있습니다."},{"id":"with-activity-29","type":"news","verified":true,"memberId":"with-medical","org":"위드의료복지사회적협동조합","category":"기관 활동","title":"2025년 대구시 사회적경제 통합돌봄 시범사업 단체 1위로 선정","date":"2025.10.30 게시","publishedDate":"2025-10-30","url":"https://www.withmedcoop.com/bbs/board.php?bo_table=sub0204&wr_id=29&theme_type=main1","source":"위드의료복지사회적협동조합","photoKey":"with-29-1","body":"위드는 대구시 사회적경제 통합돌봄 시범사업의 선정 IR 발표에서 최우수로 선정됐다고 공식 갤러리에 알렸습니다. 지역의 통합돌봄 모델을 제안하고 선정 결과를 함께 나눈 활동입니다.\n\n사진은 해당 사업 선정 발표 현장의 기념촬영입니다."},{"id":"with-activity-30","type":"news","verified":true,"memberId":"with-medical","org":"위드의료복지사회적협동조합","category":"기관 활동","title":"사진으로 보는 제5차 위드의료복지사회적협동조합 총회","date":"2026.03.30 게시","publishedDate":"2026-03-30","url":"https://www.withmedcoop.com/bbs/board.php?bo_table=sub0204&wr_id=30&theme_type=main1","source":"위드의료복지사회적협동조합","photoKey":"with-30-10","body":"위드는 제5차 정기총회의 현장을 사진으로 공개했습니다. 조합원들이 자료를 살펴보고 발표를 들으며 함께한 총회의 모습이 담겨 있습니다.\n\n조합의 운영을 함께 만들어가는 조합원들의 활동 기록입니다."},{"id":"with-activity-31","type":"news","verified":true,"memberId":"with-medical","org":"위드의료복지사회적협동조합","category":"기관 활동","title":"위드 건강 강좌 시리즈 1탄 \"음식과 암 이야기\" 강좌 스케치","date":"2026.05.18 게시","publishedDate":"2026-05-18","url":"https://www.withmedcoop.com/bbs/board.php?bo_table=sub0204&wr_id=31&theme_type=main1","source":"위드의료복지사회적협동조합","photoKey":"with-31-1","body":"위드는 「음식과 암 이야기」를 주제로 건강강좌를 열었습니다. 기관 기록에 따르면 약 25명의 조합원과 주민이 함께 강연을 들었습니다.\n\n사진은 해당 건강강좌의 강연자와 참석자들입니다."},{"id":"dounuri-home-medical-agreement","type":"news","verified":true,"memberId":"daegu-dounuri","org":"사회적협동조합 대구도우누리","category":"기관 활동","title":"범어연합내과 재택의료센터와 대구 재가장기요양기관연합회 수성지회·대구도우누리 업무협약","date":"2026.04.03","publishedDate":"2026-04-10","url":"https://blog.naver.com/beomeo3535/224247435912","source":"사회적협동조합 대구도우누리","photoKey":"dounuri-beomeo-1","body":"대구도우누리는 2026년 4월 3일 범어연합내과 재택의료센터, 대구재가장기요양기관연합회 수성지회와 업무협약을 맺었습니다. 취약한 재가 어르신을 위한 의료와 사례관리의 연계를 함께 모색하는 협약입니다.\n\n사진은 해당 협약식의 기념촬영이며 현수막에서 기관명을 확인할 수 있습니다."},{"id":"dounuri-community-interview","type":"news","verified":true,"memberId":"daegu-dounuri","org":"사회적협동조합 대구도우누리","category":"기관 활동","title":"경영에서 돌봄으로, 사람을 이해하는 길을 걷다 | 사회적 협동 조합 대구 도우누리","date":"2026.11.10 게시","publishedDate":"2026-11-10","url":"https://blog.naver.com/thecompanyc/224471963501","source":"사회적협동조합 대구도우누리","photoKey":"dounuri-interview-37","body":"더컴퍼니씨의 2026 두근두근 소셜홍보 프로젝트에서 대구도우누리 대표의 이야기를 소개했습니다. 기관의 설립을 준비한 과정과 지역의 돌봄을 연결하려는 서비스 철학을 담았습니다.\n\n사진은 기관명이 적힌 조끼를 입고 이야기하는 대표의 실제 인터뷰 모습입니다."},{"id":"sdl-university-agreement","type":"news","verified":true,"memberId":"welfare-design","org":"사회복지디자인연구소사회적협동조합","category":"기관 활동","title":"경북대학교 사회복지학부와 상호협력을 위한 업무협약","date":"2023.07.26","publishedDate":"2023-07-27","url":"https://kwelltimes.com/news/view.php?idx=953","source":"케이웰타임즈 · 이연주 책임기자","photoKey":"sdl-agreement-1","body":"사회복지디자인연구소사회적협동조합은 2023년 7월 26일 경북대학교 사회복지학부와 상호협력을 위한 업무협약을 맺었습니다. 대학과 지역의 사회복지 조직이 협력의 기반을 마련한 자리입니다.\n\n사진은 해당 협약식에 함께한 관계자들의 기념촬영입니다."},{"id":"dgcare-practitioner-training","type":"news","verified":true,"memberId":"daegu-care","org":"대구돌봄사회적협동조합","category":"기관 활동","title":"사회복지법인 외부추천이사 및 후보군 역량강화 교육","date":"2023.05.24","publishedDate":null,"url":"https://www.gccwo.org/index.php?document_srl=16943&listStyle=viewer&mid=gccwo_board_02&page=5","source":"경상북도사회복지협의회","photoKey":"dgcare-training-1","body":"2023년 5월 24일 경상북도사회복지협의회의 사회복지법인 외부추천이사 및 후보군 역량강화 교육에 대구돌봄 소속 원대재가노인복지센터장이 강사로 참여했습니다.\n\n사회복지기관 운영에 필요한 역량을 함께 살피는 자리였으며 사진은 강의와 교육 참석자들의 모습입니다."}];
