function detail(id) {
  const item=findItem(id);
  if (!item?.type) return notFound();
  const route=contentRoutes[item.type],label=contentLabels[item.type];
  const actions=item.type==='news'?relatedStoryActions(item):'';
  const original=cleanURL(item.url);
  const paragraphs=String(item.body||'').split(/\n\s*\n/).filter(Boolean);
  const answer=item.type==='policy'?paragraphs.shift():'';
  return `<div class="wrap page-content">
    <div class="campaign-toolbar"><a class="backlink" href="#/${route}">${icon('back')} ${label} 목록</a></div>
    <div class="detail-layout"><article class="detail-main">
      <div class="tags"><span class="tag blue">${esc(item.category)}</span>${(item.type==='news'||item.type==='event')&&!item.verified?`<span class="tag demo">${item.isLocal?'등록 시연':'예시 콘텐츠'}</span>`:''}</div>
      <div class="on-article-title"><h1>${esc(item.title)}</h1>${item.type==='news'&&canPreviewShare('detail/'+id)?`<button class="icon-btn" data-action="share" aria-label="소식 공유하기">${icon('share')}</button>`:''}</div>
      <div class="detail-meta">${item.type==='policy'&&original?`<a href="${esc(original)}" target="_blank" rel="noopener noreferrer">${esc(item.org)}</a>`:esc(item.org)}${item.date?' · '+esc(item.date):''}</div>
      ${answer?`<p class="on-policy-answer">${esc(answer)}</p>`:''}
      ${item.type==='news'?articleMedia(item):item.type==='policy'?`<figure class="policy-detail-photo">${policyThumbnail(item,true)}<figcaption>${photoCredit(storyPhotoKey(item))}</figcaption></figure>`:onCoverFigure(storyPhotoKey(item))}
      <div class="bodytext">${paragraphs.map(paragraph=>`<p>${esc(paragraph)}</p>`).join('')}</div>${item.source?`<p class="network-source">출처 · ${esc(item.source)}</p>`:''}${actions}
      ${item.type==='policy'&&original?`<a class="btn primary" href="${esc(original)}" target="_blank" rel="noopener noreferrer">공식 원문 보기 ${icon('external')}</a>`:''}
      ${item.type==='resource'?`<button class="btn primary" data-action="${original?'external':'download'}" data-id="${esc(id)}">${icon(original?'external':'download')} ${original?'공식 자료실 열기':'자료 다운로드'}</button>`:''}
      ${item.past?(item.storyId?`<a class="btn" href="#/detail/${esc(item.storyId)}">관련 활동소식 보기 ${icon('arrow')}</a>`:original?`<a class="btn" href="${esc(original)}" target="_blank" rel="noopener noreferrer">활동 원문 보기</a>`:''):item.type==='event'?`<div class="specs"><div class="spec"><small>일정</small><strong>${esc(item.date||'일정 미정')}</strong></div><div class="spec"><small>장소</small><strong>확정 후 안내</strong></div></div>${note('행사 신청은 실제 일정과 접수 경로 확정 후 제공됩니다.')}`:''}
      ${item.type==='news'&&original?`<a class="btn" href="${esc(original)}" target="_blank" rel="noopener noreferrer">원문 보기 ${icon('external')}</a>`:''}
    </article><aside class="detail-aside"><h3>${label}</h3><a class="btn" href="#/${route}">${label} 전체 보기 ${icon('arrow')}</a>
      ${item.type==='news'&&!item.verified?note(item.isLocal?'브라우저에서 등록한 시연 소식입니다.':'사진은 참고 사례이며 소식은 예시입니다.'):''}</aside></div>
  </div>`;
}

function about(){return documentedAbout()}
function proposal(){return pageHead('플랫폼 구축·운영 제안','대구 통합돌봄네트워크 ON · 회원사 정보공유와 후원')+`<div class="wrap page-content"><div class="proposal-kicker"><span class="tag blue">제안 검토용 · 2026.11.20</span><a class="btn primary small" href="/downloads/daegu-care-on-proposal-20261120.pdf" download="대구 통합돌봄네트워크 ON 제안서 최종본.pdf">${icon('download')} 제안서 PDF</a><button class="btn small" data-action="print">${icon('file')} 운영안 인쇄</button></div><div class="prose"><h2 class="intro-big">먼저 정보를 모으고,<br>꾸준히 교류하는 기반을 만듭니다.</h2><p class="muted">회원사는 각자의 돌봄 사업을 알리고 모금을 운영합니다. 사무국은 회원사 정보와 등록 요청을 관리합니다. 실제 매출 연계와 공동사업 실행 기능은 향후 별도 협의를 거쳐 확장합니다.</p></div><section class="proposal-section"><div class="step">01 / BUILD SCOPE</div><h2>초기 구축과 향후 확장</h2><div class="scope"><div class="scope-box"><span class="tag blue">이번 제안 · 초기 구축</span><h3>회원사와 정보를 연결하는 플랫폼</h3><ul><li>네트워크 소개 및 운영체계 안내</li><li>회원사 기업정보·서비스·외부 링크</li><li>회원사별 모금 목표·사용 계획·후원 현황 및 후원 시연</li><li>회원사 활동소식 및 사진·자료 공유</li><li>정책정보와 공식 원문 연결</li><li>교육·행사 안내 및 자료실</li><li>검색·분류 및 사무국 게시물 관리</li></ul></div><div class="scope-box future"><span class="tag demo">향후 확장 · 별도 협의</span><h3>민간협력 비즈니스 플랫폼</h3><ul><li>회원사 간 사업제휴와 서비스 연계</li><li>실제 매출 및 공동사업 성과 관리</li><li>대구병원동행사업 등 공동사업 모델</li><li>참여기업 모집·업무협약·공동홍보</li></ul><p class="smalltext muted">초기 화면의 활성 메뉴와 운영 기능에는 포함하지 않습니다.</p></div></div><div class="table-wrap"><table><thead><tr><th>초기 메뉴</th><th>제공 내용</th><th>운영 담당</th></tr></thead><tbody>${[['네트워크 소개','목적, 운영 방향, 역할 안내','사무국'],['회원사 소개','기업정보, 서비스 분야, 지역, 외부 링크','회원사 · 사무국'],['회원사 활동소식','사진, 행사, 사업과 교육 소식','회원사 · 사무국'],['통합돌봄 정책정보','정부·대구지역 정책의 공식 출처 연결','사무국'],['교육·행사 정보','교육, 세미나, 간담회 안내','사무국 · 회원사'],['자료실','정책자료, 홍보자료, 운영서식','사무국 · 회원사']].map(r=>`<tr>${r.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="proposal-section"><div class="step">02 / OPERATION</div><h2>회원사는 공유하고, 사무국은 정리합니다</h2><div class="role-list">${[['운영위원회','운영 방향과 게시 기준, 공개 범위 결정'],['사무국','회원사 정보 확인, 게시물 승인 및 정책정보 업데이트'],['회원사 담당자','기업정보 제공, 월 1회 이상 활동소식 등록 권장'],['정기 운영점검','정보의 정확성, 참여도와 사용성을 함께 점검']].map(([t,d])=>`<div class="role"><b>${t}</b><p>${d}</p></div>`).join('')}</div><p>회원사가 사진·자료와 설명을 등록하면 사무국이 내용을 확인한 후 게시하는 방식으로 제안합니다. 정책·지원사업 정보는 출처와 확인일을 함께 표시합니다.</p></section><section class="proposal-section"><div class="step">03 / ROADMAP</div><h2>준비부터 시범 운영까지</h2><div class="roadmap">${[['01','자료 취합','회원사 명단, 기본정보, 홈페이지와 활동자료 수집'],['02','플랫폼 구축','초기 메뉴와 검색, 상세 화면, 게시 흐름 구성'],['03','시범 운영','회원사별 담당자 안내, 게시물 등록과 이용 의견 수렴'],['04','평가 후 확장','참여도와 운영효과 점검 후 공동사업 기능 검토']].map(([n,t,d])=>`<div class="stage"><small>STEP ${n}</small><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><p>착수 일정, 개발 범위와 비용은 실제 회원사 수와 운영 방식, 인증·파일 저장 요구를 확인한 뒤 산정합니다.</p></section><section class="proposal-section"><div class="step">04 / SUCCESS CRITERIA</div><h2>운영의 기준도 함께 세웁니다</h2><div class="three-grid">${[['정보 완성도','등록 회원사 수, 기업정보 입력률과 정보 갱신 현황'],['참여 지속성','월간 활동소식 등록 기관 수와 게시물 승인 처리 현황'],['정보 활용도','정책·자료 열람과 이용 의견을 통해 개선점 확인']].map(([t,d])=>`<div class="value-card"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><p>위 항목은 향후 운영 지표 제안입니다. 현재 시연에 실제 이용 통계가 수집되거나 표시되는 것은 아닙니다.</p></section><section class="proposal-section"><div class="step">05 / DEMO & NEXT</div><h2>이번 시연에서 확인할 수 있는 것</h2><p>분야·지역별 회원사 찾기, 콘텐츠 상세 보기, 통합검색, 회원사·게시물 등록과 사무국 승인 흐름을 체험할 수 있습니다. 시연 입력은 현재 브라우저에만 저장됩니다. 실제 운영을 위한 로그인과 권한, 서버 저장, 파일 관리 및 개인정보 공개 기준은 다음 구축 단계에서 적용합니다.</p><div class="action-line"><a class="btn primary" href="#/home">플랫폼 둘러보기 ${icon('arrow')}</a><a class="btn" href="#/admin">운영관리 시연</a><button class="btn" data-action="template">회원사 취합 양식 ${icon('download')}</button></div></section><details class="future-detail"><summary>향후 확장 방향 자세히 보기</summary><p>궁극적으로 회원사들이 서로의 서비스를 이해하고 필요한 기업끼리 협력하여 실제 매출과 공동사업을 만들어 내는 대구 통합돌봄 민간협력 비즈니스 플랫폼으로 발전시키는 방향을 검토합니다.</p><p>대구병원동행사업을 향후 첫 공동사업 모델로 검토할 수 있습니다. 참여기업 모집, 업무협약, 서비스 연계와 공동홍보 등은 관계기관 협의와 운영체계 확정 후 별도 단계로 추가합니다.</p></details></div>`}
function matchesSearch(query,fields) {
  if (!query.trim()) return true;
  const words=query.normalize('NFKC').trim().split(/[\s·]+/).filter(Boolean);
  const normalize=value=>value.normalize('NFKC').toLowerCase().replace(/[\s·]+/g,'');
  const text=normalize(fields.filter(Boolean).join(' '));
  return words.length>0&&words.every(word=>text.includes(normalize(word)));
}
function searchPage(q){
  globalQuery=q;
  const groups=[
    ['돌봄사업',publishedProjects(),givingPath],
    ['회원사',directoryMembers(),item=>'member/'+item.id],
    ['활동소식',publishedNews()],
    ['정책정보',policies],
    ['교육·행사',items('event')],
    ['자료실',items('resource')]
  ];
  const matches=q?groups.flatMap(([kind,entries,path])=>entries
    .filter(item=>matchesSearch(q,[item.name,item.title,item.desc,item.body,item.service,item.category,item.district,item.org,
      item.owner,item.aliases?.join(' '),item.items?.join(' '),campaignFor(item)?.title,item.district?'대구광역시':'']))
    .map(item=>({item,kind,route:path?path(item):'detail/'+item.id}))):[];
  return pageHead('통합검색','')+`<div class="wrap page-content">
    <form id="global-search" class="filters" role="search" aria-label="통합검색">
      <div class="searchbox"><input name="q" type="search" value="${esc(q)}" placeholder="검색어를 입력해 주세요" aria-label="통합검색어"><button aria-label="검색">${icon('search')}</button></div>
    </form>
    <div class="result-head">${q?`‘${esc(q)}’ 검색결과 <strong>${matches.length}건</strong>`:'검색어를 입력해 주세요'}</div>
    <div class="row-list">${matches.map(({item,kind,route})=>`<a class="list-row" href="#/${esc(route)}"><div class="row-main">
      <span class="tag blue">${kind}</span><h3>${esc(item.name||item.title)}</h3><small>${esc(item.org||item.service||'')}</small></div>${icon('chevron')}</a>`).join('')||(q?empty('검색결과가 없습니다. 다른 키워드로 찾아보세요.'):'')}</div></div>`;
}

